    mutationFn: (body: { amount: string; date: string; note: string; corrects: string; ref: string; tags: string }) =>
      claim
        ? putJson<Claim>(`${claimsPath(sheet)}/${claim.id}`, body, user)
        : postJson<Claim>(personClaimsPath(sheet, person.id), body, user),

